ProbabilityTheory.HasGaussianLaw.indepFun_of_covariance_eval.{u_1, u_4, u_5} {Ω : Type u_1} {mΩ : MeasurableSpace Ω}
  {P : MeasureTheory.Measure Ω} {ι : Type u_4} {κ : Type u_5} [Finite ι] [Finite κ] {X : ι → Ω → ℝ} {Y : κ → Ω → ℝ}
  (hXY : ProbabilityTheory.HasGaussianLaw (fun ω => (fun i => X i ω, fun j => Y j ω)) P)
  (h : ∀ (i : ι) (j : κ), ProbabilityTheory.covariance (X i) (Y j) P = 0) :
  ProbabilityTheory.IndepFun (fun ω i => X i ω) (fun ω j => Y j ω) P

MeasureTheory.ProbabilityMeasure.tendsto_measure_of_null_frontier_of_tendsto'.{u_1, u_2} {Ω : Type u_1} {ι : Type u_2}
  {L : Filter ι} [MeasurableSpace Ω] [TopologicalSpace Ω] [OpensMeasurableSpace Ω] [HasOuterApproxClosed Ω]
  {μ : MeasureTheory.ProbabilityMeasure Ω} {μs : ι → MeasureTheory.ProbabilityMeasure Ω}
  (μs_lim : Filter.Tendsto μs L (nhds μ)) {E : Set Ω} (E_nullbdry : ↑μ (frontier E) = 0) :
  Filter.Tendsto (fun i => ↑(μs i) E) L (nhds (↑μ E))
